(ELM.EXAMS = ELM.EXAMS || {})["matura-podstawowa"] = {"manifest":{"id":"matura-podstawowa","label":"Matura podstawowa","title":"Matura podstawowa z angielskiego","route":"/matura-podstawowa","sections":[{"id":"start","label":"Start","pages":[{"id":"przeglad","file":"strony/przeglad.md","label":"Przegląd egzaminu"},{"id":"plan-powtorki","file":"strony/plan-powtorki.md","label":"Plan powtórki"}]},{"id":"czesci","label":"Części egzaminu","pages":[{"id":"sluchanie","file":"strony/sluchanie.md","label":"Słuchanie"},{"id":"czytanie","file":"strony/czytanie.md","label":"Czytanie"},{"id":"srodki-jezykowe","file":"strony/srodki-jezykowe.md","label":"Środki językowe"},{"id":"wypowiedz-pisemna","file":"strony/wypowiedz-pisemna.md","label":"Wypowiedź pisemna"},{"id":"matura-ustna","file":"strony/matura-ustna.md","label":"Matura ustna"}]},{"id":"przygotowanie","label":"Przygotowanie","pages":[{"id":"gramatyka-pod-egzamin","file":"strony/gramatyka-pod-egzamin.md","label":"Gramatyka pod egzamin"},{"id":"slownictwo-tematyczne","file":"strony/slownictwo-tematyczne.md","label":"Słownictwo tematyczne"},{"id":"dzien-egzaminu","file":"strony/dzien-egzaminu.md","label":"Dzień egzaminu"}]},{"id":"cwiczenia","label":"Ćwiczenia","exerciseGroups":[{"part":"sluchanie","label":"Słuchanie","sets":[{"id":"mp-sluchanie-1","file":"cwiczenia/mp-sluchanie-1.json","label":"6 nagrań","maxScore":6}]},{"part":"czytanie","label":"Czytanie","sets":[{"id":"mp-czytanie-1","file":"cwiczenia/mp-czytanie-1.json","label":"Blog o telefonie","maxScore":5},{"id":"mp-czytanie-2","file":"cwiczenia/mp-czytanie-2.json","label":"Prawda, fałsz, brak informacji","maxScore":7}]},{"part":"srodki","label":"Środki językowe","sets":[{"id":"mp-minidialogi-1","file":"cwiczenia/mp-minidialogi-1.json","label":"Mini-dialogi","maxScore":6},{"id":"mp-srodki-cloze-1","file":"cwiczenia/mp-srodki-cloze-1.json","label":"Luki: wybór","maxScore":8},{"id":"mp-srodki-slowotworstwo-1","file":"cwiczenia/mp-srodki-slowotworstwo-1.json","label":"Słowotwórstwo","maxScore":8},{"id":"mp-srodki-transformacje-1","file":"cwiczenia/mp-srodki-transformacje-1.json","label":"Transformacje","maxScore":8},{"id":"mp-srodki-tlumaczenie-1","file":"cwiczenia/mp-srodki-tlumaczenie-1.json","label":"Tłumaczenie fragmentów","maxScore":6}]}]},{"id":"trening","label":"Trenery","trainers":[{"id":"trening-pisanie","file":"trening/pisanie.json","label":"Wypowiedź pisemna","type":"writing"},{"id":"trening-mowienie","file":"trening/mowienie.json","label":"Trener matury ustnej","type":"speaking"}]}],"links":[{"label":"Informator CKE","url":"https://cke.gov.pl"}]},"pages":{"przeglad":"---\nid: przeglad\ntitle: Przegląd matury podstawowej z angielskiego\nsection: start\norder: 1\nsummary: Jak wygląda egzamin pisemny i ustny, ile trwa, ile punktów i jaki jest próg.\n---\n\n# Przegląd matury podstawowej z angielskiego\n\n> Dane zebrane z informatora CKE (Formuła 2023) i opracowań. Źródła różnią się w drobiazgach, dlatego przed egzaminem sprawdź aktualny informator i komunikat na [cke.gov.pl](https://cke.gov.pl). Stan: październik 2026.\n\n## Część pisemna\n\n- Czas: **120 minut**. Maksimum: **60 punktów**.\n- Poziom: **B1** (słuchanie i czytanie bywają na B1+).\n- Próg zdawalności: **30% punktów**, czyli 18 z 60. Dotyczy części pisemnej i ustnej osobno.\n- Termin 2027 (do potwierdzenia na cke.gov.pl): główny termin angielskiego podstawowego **6 maja 2027, godz. 9:00**.\n\n| Część | Zadań | Punkty | Co robisz |\n| --- | --- | --- | --- |\n| Rozumienie ze słuchu | 15 | 15 | słuchasz nagrań (dwa razy), zaznaczasz, dobierasz, uzupełniasz |\n| Rozumienie tekstów pisanych | 20 | 20 | czytasz teksty (łącznie ok. 1100–1500 wyrazów) i odpowiadasz |\n| Znajomość środków językowych | 13 | 13 | luki, słowotwórstwo, transformacje, tłumaczenie fragmentów, mini-dialogi |\n| Wypowiedź pisemna | 1 | 12 | e-mail, wpis na blogu lub forum, 100–150 wyrazów |\n\n## Część ustna\n\n- Osobny egzamin, w szkole, w terminie ustalonym przez szkołę (zwykle kilka tygodni przed pisemną).\n- Trwa około **15 minut**: rozmowa wstępna i trzy zadania.\n- Wynik w procentach. Szczegóły: [[matura-ustna]].\n\n## Jak korzystać z tego modułu\n\n1. Zacznij od [[plan-powtorki]].\n2. Każdą część arkusza ćwicz zestawami z tego modułu.\n3. Co tydzień jeden tekst w trenerze pisania.\n4. Wracaj do dziennika błędów.\n","plan-powtorki":"---\nid: plan-powtorki\ntitle: Plan powtórki na 10 tygodni\nsection: start\norder: 2\nsummary: Tygodniowy plan do matury podstawowej, od diagnozy do spokojnego końca.\n---\n\n# Plan powtórki na 10 tygodni\n\n4–5 krótkich sesji w tygodniu po 30–45 minut. Przy mniejszej ilości czasu zrób 3 sesje, ale regularnie.\n\n| Tydzień | Cel | Co robisz |\n| --- | --- | --- |\n| 1 | Diagnoza | [[przeglad]], po jednym zestawie z każdej części, zobacz statystyki |\n| 2 | Czasy | Wszystkie czasy z [[gramatyka-pod-egzamin]], zestawy czasów |\n| 3 | Środki językowe 1 | Luki wielokrotnego wyboru, mini-dialogi |\n| 4 | Środki językowe 2 | Słowotwórstwo i transformacje |\n| 5 | Czytanie | Strategie z [[czytanie]], dwa teksty |\n| 6 | Słuchanie | Strategie z [[sluchanie]], zestaw ze słuchu, powtórka słownictwa |\n| 7 | Pisanie 1 | E-mail, trener pisania |\n| 8 | Pisanie 2 | Wpis na blogu i forum, samoocena wg kryteriów |\n| 9 | Ustna | [[matura-ustna]], ćwiczenia z nagrywaniem się telefonem |\n| 10 | Powtórka | Dziennik błędów, [[dzien-egzaminu]]. Bez nowego materiału w ostatnie dni |\n\nZasada: najpierw to, co wychodzi najsłabiej według statystyk.\n","sluchanie":"---\nid: sluchanie\ntitle: Rozumienie ze słuchu\nsection: czesci\norder: 1\nsummary: Strategie do nagrań maturalnych: przed, w trakcie i po odsłuchu.\n---\n\n# Rozumienie ze słuchu\n\n15 zadań, 15 punktów. Każde nagranie słyszysz **dwa razy**. Całość trwa około 25 minut.\n\n## Przed nagraniem\n\n1. Przeczytaj polecenie i opcje. Zrozum, o co pytają.\n2. Podkreśl słowa kluczowe (liczby, miejsca, osoby, powody).\n3. Przewidź, jakich słów możesz się spodziewać.\n\n## Pierwszy odsłuch\n\n- Zaznaczaj tylko to, czego jesteś pewien.\n- Zapisuj liczby i godziny skrótem.\n- Nie zatrzymuj się na jednym nieznanym słowie.\n\n## Drugi odsłuch\n\n- Sprawdzasz te zadania, które zostawiłeś.\n- Słuchaj słów zmieniających sens: but, however, actually, in fact, not really.\n\n## Typowe typy zadań\n\n- **Wybór wielokrotny (ABC lub ABCD).** Odpowiedź musi wynikać z nagrania, nie z tego, co wiesz o świecie.\n- **Dobieranie.** Każda opcja raz. Dopasowujesz wypowiedzi do osób lub tematów.\n- **Uzupełnianie luk.** Wpisujesz słowa lub liczby usłyszane w nagraniu. Pisownia ma znaczenie, gdy zmienia znaczenie.\n\n## Pułapki\n\n- **Korekta w trakcie:** „at five... no, sorry, six”. Liczy się ostatnia wersja.\n- **Wszystkie opcje padają w nagraniu.** Wybierasz tę, która odpowiada na pytanie.\n- **Podobne słowa:** fifteen i fifty, the weather i whether.\n\nĆwicz zestawem ze słuchu (syntezator mowy w przeglądarce). To trening rozumienia, nagranie egzaminacyjne brzmi inaczej.\n","czytanie":"---\nid: czytanie\ntitle: Rozumienie tekstów pisanych\nsection: czesci\norder: 2\nsummary: Strategie czytania i typy zadań w części czytania matury podstawowej.\n---\n\n# Rozumienie tekstów pisanych\n\n20 zadań, 20 punktów. Teksty mają razem około 1100–1500 wyrazów: ogłoszenia, e-maile, artykuły, wpisy, recenzje.\n\n## Strategia\n\n1. Przeczytaj polecenie i pytania, potem tekst.\n2. Przeczytaj tekst raz do końca.\n3. Wróć do pytań i znajdź dowód w tekście. Zaznacz fragment.\n4. Eliminuj odpowiedzi, które są w tekście, ale odpowiadają na inne pytanie.\n\n## Typy zadań\n\n- **Wybór wielokrotny.** Dystraktory brzmią podobnie do tekstu. Sprawdź kontekst.\n- **Dobieranie.** Dopasuj nagłówki, zdania lub osoby. Każda opcja raz.\n- **Uzupełnianie zdań (wstawianie).** Fragment musi pasować logicznie i gramatycznie.\n- **Prawda / fałsz / brak informacji.** Brak informacji znaczy, że tekst o tym nie mówi.\n- **Odpowiedzi na pytania.** Krótka odpowiedź z tekstu, bez przepisywania całego zdania.\n\n## Pułapki\n\n- Parafrazy: w tekście „cheap”, w pytaniu „not expensive”.\n- Słowa absolutne: always, never, only, all.\n- Liczby i daty w opcjach, w tekście jest inna.\n\nSłownictwo: [[slownictwo-tematyczne]].\n","srodki-jezykowe":"---\nid: srodki-jezykowe\ntitle: Znajomość środków językowych\nsection: czesci\norder: 3\nsummary: Luki, słowotwórstwo, transformacje, tłumaczenie fragmentów i mini-dialogi.\n---\n\n# Znajomość środków językowych\n\n13 zadań, 13 punktów. Odpowiedzi muszą być **w pełni poprawne gramatycznie i ortograficznie**.\n\n## Typy\n\n- **Mini-dialogi.** Wybierz reakcję lub uzupełnij wymianę.\n- **Luki (wybór lub wpisanie).** Czas, przyimek, przedimek, słowo funkcyjne.\n- **Słowotwórstwo.** Z podanego słowa (np. HAPPY) zrób właściwą formę (happiness, unhappy).\n- **Transformacje.** Przekształć zdanie tak, by znaczyło to samo, często z podanym słowem.\n- **Tłumaczenie fragmentów.** Przełóż fragment z polskiego, zachowując sens.\n- **Zestawy leksykalne.** Dopasuj grupy słów lub wybierz słowo pasujące do reszty.\n\n## Słowotwórstwo – ściąga\n\n| Zmiana | Przykłady |\n| --- | --- |\n| przymiotnik z rzeczownika | help → helpful, danger → dangerous |\n| przeczenie | happy → unhappy, polite → impolite |\n| rzeczownik z czasownika | decide → decision, move → movement |\n| przysłówek | careful → carefully |\n| osoba | teach → teacher, visit → visitor |\n\n## Transformacje – schemat\n\n1. Znajdź, co się zmienia w zdaniu: strona bierna, mowa zależna, okres warunkowy, stopniowanie.\n2. Użyj podanego słowa bez zmiany.\n3. Przeczytaj gotowe zdanie na głos w myślach.\n\nPowiązane tematy: [[b1-gramatyka-strona-bierna]], [[b1-gramatyka-mowa-zalezna]], [[b1-gramatyka-conditionals-0-1-2]].\n","wypowiedz-pisemna":"---\nid: wypowiedz-pisemna\ntitle: Wypowiedź pisemna – e-mail, blog, forum\nsection: czesci\norder: 4\nsummary: Jak zdobyć 12 punktów: treść, spójność, zakres i poprawność.\n---\n\n# Wypowiedź pisemna\n\nPiszesz **jeden tekst**: e-mail, wpis na blogu lub post na forum. Długość: **100–150 wyrazów**. Polecenie ma **cztery punkty**, do których musisz się odnieść.\n\n## Punktacja (12 punktów)\n\n| Kryterium | Punkty |\n| --- | --- |\n| Treść | 0–5 |\n| Spójność i logika | 0–2 |\n| Zakres środków językowych | 0–3 |\n| Poprawność środków językowych | 0–2 |\n\nZasady:\n- Poniżej **80 wyrazów** ocenia się tylko treść.\n- Za pominięcie jednego z czterech punktów maksimum za treść spada.\n- Błędy interpunkcyjne na tym poziomie nie obniżają oceny. Pisownia już tak.\n- Przekroczenie 150 wyrazów nie jest karane wprost, ale daje więcej okazji do błędów.\n\n## Plan tekstu (ok. 120 wyrazów)\n\n1. **Wstęp** (1–2 zdania): powód pisania, pozdrowienie.\n2. **Punkt 1** (2 zdania).\n3. **Punkt 2** (2 zdania).\n4. **Punkt 3** (2 zdania).\n5. **Punkt 4** (2 zdania).\n6. **Zakończenie** (1 zdanie) i pożegnanie.\n\n## Zwroty\n\n- E-mail: Thanks for your message. / I'm writing to... / Could you tell me...? / Write back soon.\n- Blog: Last weekend... / It was amazing because... / My advice is...\n- Forum: In my opinion... / I'd recommend... / Has anyone...?\n\n## Łączniki\n\nand, but, so, because, although, however, first, then, finally, in addition.\n\n## Lista kontrolna\n\n- Wszystkie 4 punkty?\n- 100–150 wyrazów?\n- Czas przeszły i teraźniejszy tam, gdzie trzeba?\n- Pisownia i szyk?\n\nTrener pisania w tym module ma wzorcowe odpowiedzi.\n","matura-ustna":"---\nid: matura-ustna\ntitle: Matura ustna\nsection: czesci\norder: 5\nsummary: Jak wygląda egzamin ustny z angielskiego i jak go ćwiczyć w domu.\n---\n\n# Matura ustna\n\n> Szczegóły (punktacja, czas przygotowania) sprawdź w informatorze CKE i w szkole. W opracowaniach podawane są różne wartości, dlatego tutaj opisujemy strukturę i strategie, a nie liczby.\n\n## Przebieg (ok. 15 minut)\n\n1. **Rozmowa wstępna.** Krótkie pytania o Ciebie: rodzina, zainteresowania, dzień.\n2. **Zadanie 1: rozmowa z odgrywaniem roli.** Odnosisz się do czterech elementów polecenia i podtrzymujesz rozmowę.\n3. **Zadanie 2: opis ilustracji** i odpowiedzi na pytania o jej temat.\n4. **Zadanie 3: wybór ilustracji** z materiału, uzasadnienie wyboru i odpowiedzi na pytania.\n\nEgzaminuje Cię nauczyciel w obecności drugiego członka zespołu, który nie bierze udziału w rozmowie.\n\n## Strategie\n\n- **Mów pełnymi zdaniami.** Jedno słowo to za mało.\n- **Rozwijaj odpowiedź:** powód, przykład, opinia.\n- **Gdy zapomnisz słowa,** opisz je: „the thing you use to...”.\n- **Spójniki:** and, but, because, so, although.\n- **Opis ilustracji:** Where? Who? What are they doing? What is the atmosphere? What do I think?\n\n## Zwroty do opisu obrazka\n\n- In the picture I can see...\n- In the foreground / background / on the left...\n- They seem to be... / It looks like...\n- I think they are feeling...\n\n## Zwroty do wyboru\n\n- I'd choose picture A because...\n- I wouldn't choose B because...\n- The best option is... as...\n\n## Jak ćwiczyć w domu\n\n1. Weź pytanie i nagraj telefonem 1 minutę odpowiedzi.\n2. Odsłuchaj: czy mówisz płynnie, bez długich przerw?\n3. Powtórz nagranie, dodając jeden powód i jeden przykład.\n4. Nagrania zostają tylko na Twoim telefonie.\n\n## Trener matury ustnej\n\nW aplikacji możesz ćwiczyć wszystkie części: losujesz kartę, mówisz na czas, nagrywasz się i odsłuchujesz. Czasy w trenerze są orientacyjne, a aktualny przebieg i punktację sprawdź w informatorze CKE.\n\n[Otwórz trener matury ustnej](#/matura-podstawowa/trening-mowienie)\n","gramatyka-pod-egzamin":"---\nid: gramatyka-pod-egzamin\ntitle: Gramatyka pod maturę podstawową\nsection: przygotowanie\norder: 1\nsummary: Tematy gramatyczne, które wracają na maturze podstawowej, z odnośnikami.\n---\n\n# Gramatyka pod maturę podstawową\n\n## Czasy\n\n- [[a1-czasy-present-simple]], [[a1-czasy-present-continuous]]\n- [[a2-czasy-past-simple]], [[a2-czasy-past-continuous]]\n- [[a2-czasy-present-perfect-doswiadczenia]]\n- [[b1-czasy-present-perfect-vs-past-simple]], [[b1-czasy-present-perfect-continuous]]\n- [[b1-czasy-past-perfect]]\n- [[b1-czasy-wybor-formy-przyszlej]], [[b1-czasy-used-to]]\n\n## Gramatyka\n\n- [[a2-gramatyka-stopniowanie-przymiotnikow]]\n- [[a2-gramatyka-policzalne-niepoliczalne]]\n- [[a2-gramatyka-modalne-must-should]]\n- [[a2-gramatyka-spojniki]]\n- [[a2-gramatyka-czasownik-ing-to]]\n- [[b1-gramatyka-conditionals-0-1-2]]\n- [[b1-gramatyka-strona-bierna]]\n- [[b1-gramatyka-mowa-zalezna]]\n- [[b1-gramatyka-zdania-wzgledne]]\n- [[b1-gramatyka-modalne-przypuszczenia]]\n- [[b1-gramatyka-pytania-posrednie]]\n- [[b1-gramatyka-too-enough-so-such]]\n\n## Funkcje\n\n- [[b1-funkcje-opinia]], [[b1-funkcje-zgoda-niezgoda]]\n- [[b1-funkcje-rady]], [[b1-funkcje-skargi]]\n- [[b1-funkcje-plany-marzenia]], [[b1-funkcje-opowiadanie-historii]]\n- [[b1-funkcje-strategie-ratunkowe]], [[b1-funkcje-podtrzymywanie-rozmowy]] (przydatne na ustnej)\n\n## Kolejność nauki\n\nCzasy, potem tryby warunkowe i strona bierna, na końcu mowa zależna i zdania względne.\n","slownictwo-tematyczne":"---\nid: slownictwo-tematyczne\ntitle: Słownictwo tematyczne\nsection: przygotowanie\norder: 2\nsummary: Obszary tematyczne wymagane na maturze podstawowej z przykładami.\n---\n\n# Słownictwo tematyczne\n\nPodstawa programowa obejmuje te obszary. To lista startowa.\n\n| Temat | Przykładowe słowa i zwroty |\n| --- | --- |\n| Człowiek | appearance, personality, relationship, generous, shy |\n| Dom | tenant, rent, neighbourhood, furniture, move house |\n| Szkoła | exam, grade, timetable, revise, cheat, scholarship |\n| Praca | employer, salary, apply for a job, part-time, experience |\n| Życie rodzinne i towarzyskie | get on with, argue, celebrate, generation gap |\n| Żywienie | vegetarian, recipe, ingredients, fast food, balanced diet |\n| Zakupy i usługi | refund, discount, receipt, bargain, customer service |\n| Podróżowanie i turystyka | accommodation, sightseeing, delay, board, souvenir |\n| Kultura | exhibition, festival, review, performance, audience |\n| Sport | tournament, coach, training, injury, champion |\n| Zdrowie | symptom, prescription, recover, insurance, healthy lifestyle |\n| Nauka i technika | device, invention, social media, data, privacy |\n| Świat przyrody | environment, pollution, recycling, endangered, climate |\n| Państwo i społeczeństwo | government, election, volunteer, equality, charity |\n\n## Jak się uczyć\n\n1. Jeden temat w tygodniu, 15–20 słów i 5 zdań własnych.\n2. Kolokacje zamiast pojedynczych słów: make a decision, take a break, do homework.\n3. Błędy z dziennika dopisuj do list.\n\nZobacz też: [[b1-slownictwo]].\n","dzien-egzaminu":"---\nid: dzien-egzaminu\ntitle: Dzień egzaminu – co pamiętać\nsection: przygotowanie\norder: 3\nsummary: Krótka lista rzeczy do zapamiętania na maturę pisemną i ustną.\n---\n\n# Dzień egzaminu\n\nSzczegóły (godzina, sala, dokument, przybory) sprawdź w komunikacie szkoły i w informacji CKE.\n\n## Dzień wcześniej\n\n- Spakuj dokument tożsamości i przybory (czarny długopis).\n- Nie ucz się nowych rzeczy.\n- Połóż się o normalnej porze.\n\n## Rano\n\n- Zjedz śniadanie i wyjdź z zapasem czasu.\n- Zostaw telefon i urządzenia zgodnie z regulaminem.\n\n## Podział czasu (120 minut, propozycja)\n\n| Część | Czas |\n| --- | --- |\n| Słuchanie | ok. 25 min (zgodnie z nagraniem) |\n| Czytanie | ok. 30 min |\n| Środki językowe | ok. 20 min |\n| Wypowiedź pisemna | ok. 25 min |\n| Zapas i przeniesienie odpowiedzi | ok. 15–20 min |\n\n## Zasady\n\n1. Nie zostawiaj pustych odpowiedzi w zadaniach zamkniętych.\n2. Pisanie zaczynaj od planu na brudnopisie, jeśli jest dozwolony.\n3. Policz wyrazy i sprawdź, czy odniosłeś się do wszystkich punktów.\n4. Przenieś odpowiedzi na kartę, jeśli arkusz tego wymaga.\n\n## Ustna\n\n- Mów pełnymi zdaniami, nie milcz. Parafrazuj, gdy nie znasz słowa.\n- Pytanie można poprosić o powtórzenie.\n\n## Gdy pojawi się stres\n\nTrzy spokojne oddechy. Przeczytaj polecenie jeszcze raz, powoli. Pamiętaj: do zdania wystarczy 30%.\n"},"trainers":{"trening-pisanie":{"id":"trening-pisanie","timeMinutes":25,"wordRange":[100,150],"targetRange":[110,140],"warnBelow":80,"rubric":[{"id":"tresc","label":"Treść","max":5},{"id":"spojnosc","label":"Spójność i logika","max":2},{"id":"zakres","label":"Zakres środków językowych","max":3},{"id":"poprawnosc","label":"Poprawność środków językowych","max":2}],"genericChecklist":["Czy odniosłem/am się do wszystkich 4 punktów?","Czy mam 100–150 wyrazów?","Czy zakończyłem/am tekst pożegnaniem?","Czy sprawdziłem/am pisownię i czasy?"],"tasks":[{"id":"email-exchange","genre":"email","part":1,"title":"E-mail do kolegi z zagranicy","opening":"Hi Ben,","prompt":"Piszesz e-mail do kolegi z Anglii, który przyjedzie do Ciebie na wymianę szkolną.\n\nW tekście:\n• napisz, jak spędzicie pierwszy dzień\n• poinformuj, jaką pogodę zwykle ma Polska w tym miesiącu\n• zapytaj o jego dietę lub alergie\n• zaproponuj miejsce, które chcesz mu pokazać","bullets":["napisz, jak spędzicie pierwszy dzień","poinformuj, jaką pogodę zwykle ma Polska w tym miesiącu","zapytaj o jego dietę lub alergie","zaproponuj miejsce, które chcesz mu pokazać"],"points":12,"genreChecklist":["Czy odniosłem/am się do wszystkich 4 punktów?","Czy mam 100–150 wyrazów?","Czy mam wstęp i zakończenie?"],"model":"Hi Ben,\nThanks for your last message. I'm really happy that you are coming to Poland! On your first day we will have lunch at my house and then I'll show you around our school. You can meet my friends there. In October the weather here is usually cool and sometimes rainy, so please bring a warm jacket and an umbrella.\nCould you tell me if you are on a special diet or if you have any allergies? My mum is planning the menu and she wants to be sure that you can eat everything. I'd also like to take you to the old town on Saturday because it is beautiful and there are many cafés there. I'm sure you will love it.\nWrite back soon,\nXYZ","modelNotes":{"summary":["Wszystkie cztery podpunkty polecenia mają osobne zdania: pierwszy dzień, pogoda, dieta i alergie oraz miejsce do pokazania.","Tekst ma dwa akapity i wyraźną logikę: najpierw plan i pogoda, potem pytanie o dietę i propozycja wycieczki.","Ton jest przyjazny i swobodny, a zdania są poprawne i zróżnicowane (will, I'll, Present Continuous, I'd like).","Uzasadnienie miejsca (beautiful) jest ogólnikowe – to najsłabsze zdanie tekstu."],"annotations":[{"anchor":"Thanks for your last message","type":"struktura","criterion":"spojnosc","note":"Nawiązanie do poprzedniej wiadomości: odpowiedź wpisuje się w korespondencję, a nie zaczyna od zera."},{"anchor":"I'm really happy that you are coming to Poland","type":"rejestr","criterion":"zakres","note":"Skrót I'm i emocjonalna fraza (really happy) – typowy, przyjazny ton listu do kolegi z wymiany."},{"anchor":"On your first day we will have lunch at my house","type":"punkty","criterion":"tresc","element":1,"note":"Podpunkt 1: jak spędzicie pierwszy dzień. Will + konkretny plan (obiad w domu)."},{"anchor":"and then I'll show you around our school","type":"lacznik","criterion":"spojnosc","note":"And then układa plan dnia w kolejności – obiad, potem szkoła."},{"anchor":"In October the weather here is usually cool and sometimes rainy","type":"punkty","criterion":"tresc","element":2,"note":"Podpunkt 2: pogoda w październiku. Usually i sometimes pokazują zakres częstotliwości, a nie jedną etykietę."},{"anchor":"if you are on a special diet or if you have any allergies","type":"punkty","criterion":"tresc","element":3,"note":"Podpunkt 3: pytanie o dietę i alergie – obie części polecenia są w jednym pytaniu pośrednim."},{"anchor":"My mum is planning the menu and she wants to be sure","type":"zakres","criterion":"zakres","note":"Present Continuous dla planu i uzasadnienie pytania – struktura wykraczająca poza samo pytanie."},{"anchor":"because it is beautiful and there are many cafés there","type":"uwaga","criterion":"zakres","note":"Do poprawy: beautiful to ogólnik. Konkret (np. the market square and old houses) uczyniłby propozycję barwniejszą."},{"anchor":"I'd also like to take you to the old town on Saturday","type":"punkty","criterion":"tresc","element":4,"note":"Podpunkt 4: miejsce do pokazania z terminem. I'd like to take you to… to uprzejma, naturalna propozycja."}]}},{"id":"blog-trip","genre":"blog","part":1,"title":"Wpis na blogu – wycieczka","opening":"Hello everyone!","prompt":"Prowadzisz bloga o podróżach. Napisz relację z niedawnej wycieczki.\n\nW tekście:\n• napisz, dokąd pojechałeś/aś i z kim\n• opisz, co najbardziej Ci się podobało\n• wspomnij o problemie, który się pojawił\n• poradź czytelnikom, czy warto tam jechać","bullets":["napisz, dokąd pojechałeś/aś i z kim","opisz, co najbardziej Ci się podobało","wspomnij o problemie, który się pojawił","poradź czytelnikom, czy warto tam jechać"],"points":12,"genreChecklist":["Czy odniosłem/am się do wszystkich 4 punktów?","Czy mam 100–150 wyrazów?","Czy mam wstęp i zakończenie?"],"model":"Hello everyone!\nLast weekend I went to Kraków with my class. We travelled by train, and it took about three hours. The best part of the trip was the visit to Wawel Castle, because the view of the river was fantastic and our guide told us many interesting stories.\nUnfortunately, there was a problem on Sunday. Our train was delayed and we waited at the station for an hour, so we were tired when we got home. However, it did not spoil the whole trip.\nI think you should definitely go to Kraków if you have time. Book your tickets early and wear comfortable shoes, because you will walk a lot. See you next time!\nXYZ","modelNotes":{"summary":["Wpis zawiera wszystkie cztery podpunkty: dokąd i z kim, ulubiony moment, problem i rada dla czytelników.","Akapity mają jasne role: relacja z wyjazdu, problem w osobnym akapicie i zakończenie z radami.","Zastosowano łącznik kontrastu (However), przysłówek postawy (Unfortunately) i uzasadnienia (because), więc tekst jest spójny.","Jedno zdanie zajmuje miejsce w limicie bez wpływu na treść – to dobra okazja, by zobaczyć, jak planować słowa."],"annotations":[{"anchor":"Last weekend I went to Kraków with my class","type":"punkty","criterion":"tresc","element":1,"note":"Podpunkt 1: dokąd i z kim – Past Simple, miejsce i towarzystwo w jednym zdaniu."},{"anchor":"We travelled by train, and it took about three hours","type":"uwaga","criterion":"tresc","note":"Do poprawy: poprawna, ale zbędna informacja – nie dotyczy żadnego podpunktu, a zajmuje miejsce w limicie. Lepiej dodać szczegół o ulubionym momencie."},{"anchor":"The best part of the trip was the visit to Wawel Castle","type":"punkty","criterion":"tresc","element":2,"note":"Podpunkt 2: co podobało się najbardziej – jasne wskazanie z superlatywem (the best)."},{"anchor":"the view of the river was fantastic and our guide told us many interesting stories","type":"zakres","criterion":"zakres","note":"Dwa konkretne powody po because: widok i przewodnik. Fantastic jest poprawne, ale podstawowe – można je zastąpić np. breathtaking. Fantastic i interesting stories to bogatsze słownictwo niż nice."},{"anchor":"Unfortunately, there was a problem on Sunday","type":"struktura","criterion":"spojnosc","note":"Początek nowego akapitu zapowiada problem – czytelnik wie, że zmienia się temat."},{"anchor":"Our train was delayed and we waited at the station for an hour","type":"punkty","criterion":"tresc","element":3,"note":"Podpunkt 3: opis problemu – opóźniony pociąg, z konsekwencją (godzina oczekiwania)."},{"anchor":"However, it did not spoil the whole trip","type":"lacznik","criterion":"spojnosc","note":"However wyraźnie przeciwstawia problem ogólnej ocenie wyjazdu – dobry łącznik kontrastu."},{"anchor":"I think you should definitely go to Kraków if you have time","type":"punkty","criterion":"tresc","element":4,"note":"Podpunkt 4: rada dla czytelników. Should + definitely wyraźnie podpowiada decyzję."},{"anchor":"Book your tickets early and wear comfortable shoes","type":"rejestr","criterion":"zakres","note":"Tryb rozkazujący skierowany do czytelników – ton bloga, nie oficjalnego tekstu."}]}},{"id":"forum-sport","genre":"forum","part":1,"title":"Wpis na forum – sport","opening":"Hi everyone,","prompt":"Na forum młodzieżowym ktoś pyta o pomysły na sport po szkole. Napisz odpowiedź.\n\nW tekście:\n• napisz, jaki sport uprawiasz i jak często\n• wyjaśnij, dlaczego go lubisz\n• opowiedz o ostatnim meczu lub treningu\n• zaproponuj, czy ta osoba może do Ciebie dołączyć","bullets":["napisz, jaki sport uprawiasz i jak często","wyjaśnij, dlaczego go lubisz","opowiedz o ostatnim meczu lub treningu","zaproponuj, czy ta osoba może do Ciebie dołączyć"],"points":12,"genreChecklist":["Czy odniosłem/am się do wszystkich 4 punktów?","Czy mam 100–150 wyrazów?","Czy mam wstęp i zakończenie?"],"model":"Hi everyone,\nI saw your question about sport after school and I'd like to share my experience. I play basketball twice a week with my school team. We train on Tuesdays and Thursdays and we have a match every second Saturday.\nI love this sport because it is fast and I can spend time with my friends. It also helps me forget about homework and stress. Last Saturday we played against another school and we won by four points! I scored six points myself, so I was really proud.\nIf you want to try it, you can join us next Thursday at 5 p.m. in the school gym. We always need new players, and nobody will laugh at you if you make mistakes. Let me know!\nXYZ","modelNotes":{"summary":["Wpis odpowiada na pytanie z forum i realizuje wszystkie podpunkty: sport i częstotliwość, powód, ostatni mecz i zaproszenie.","Narracja jest konkretna (twice a week, won by four points), co przekonuje egzaminatora o prawdziwości relacji.","Ton jest rozmowny, z bezpośrednim zwrotem do pytającego i prostym zaproszeniem.","Jedno zdanie powtarza wcześniejszą informację i zabiera słowa z limitu."],"annotations":[{"anchor":"I saw your question about sport after school and I'd like to share my experience","type":"struktura","criterion":"spojnosc","note":"Pierwsze zdanie nawiązuje do pytania z forum i zapowiada, co będzie dalej."},{"anchor":"I play basketball twice a week with my school team","type":"punkty","criterion":"tresc","element":1,"note":"Podpunkt 1: jaki sport i jak często – twice a week to konkretna częstotliwość."},{"anchor":"We train on Tuesdays and Thursdays and we have a match every second Saturday","type":"uwaga","criterion":"zakres","note":"Do poprawy: szczegóły powtarzają twice a week i nie służą żadnemu podpunktowi. Miejsce w limicie lepiej wykorzystać na powód lub mecz."},{"anchor":"because it is fast and I can spend time with my friends","type":"punkty","criterion":"tresc","element":2,"note":"Podpunkt 2: dlaczego lubię ten sport – dwa powody połączone and."},{"anchor":"It also helps me forget about homework and stress","type":"lacznik","criterion":"spojnosc","note":"Also dodaje trzeci powód i porządkuje uzasadnienie w jednym akapicie."},{"anchor":"Last Saturday we played against another school and we won by four points","type":"punkty","criterion":"tresc","element":3,"note":"Podpunkt 3: ostatni mecz. Przeciwnik i wynik pokazują, że to relacja z konkretnego wydarzenia."},{"anchor":"nobody will laugh at you if you make mistakes","type":"zakres","criterion":"zakres","note":"Pierwszy okres warunkowy w zdaniu pokazującym empatię – poprawny i naturalny, dobrze dopasowany do rozmówcy."},{"anchor":"you can join us next Thursday at 5 p.m. in the school gym","type":"punkty","criterion":"tresc","element":4,"note":"Podpunkt 4: zaproszenie z terminem i miejscem – konkretne i łatwe do zrealizowania."},{"anchor":"Let me know","type":"rejestr","criterion":"zakres","note":"Krótka prośba o odpowiedź – ton forum, bez formuł z listu formalnego."}]}},{"id":"email-complaint","genre":"email","part":1,"title":"E-mail – reklamacja","opening":"Dear Sir or Madam,","prompt":"Kupiłeś/aś w internetowym sklepie słuchawki, które nie działają. Napisz e-mail do sklepu.\n\nW tekście:\n• napisz, co kupiłeś/aś i kiedy\n• opisz, na czym polega problem\n• zapytaj, czy możesz dostać zwrot pieniędzy lub nowy produkt\n• poproś o szybką odpowiedź","bullets":["napisz, co kupiłeś/aś i kiedy","opisz, na czym polega problem","zapytaj, czy możesz dostać zwrot pieniędzy lub nowy produkt","poproś o szybką odpowiedź"],"points":12,"genreChecklist":["Czy odniosłem/am się do wszystkich 4 punktów?","Czy mam 100–150 wyrazów?","Czy mam wstęp i zakończenie?"],"model":"Dear Sir or Madam,\nI'm writing to complain about a product that I bought from your shop. On 3 October I ordered a pair of wireless headphones, and they arrived two days later.\nUnfortunately, the left headphone does not work at all, and the sound in the right one is very quiet. I have charged them several times, but nothing has changed. I have attached a photo of the product and a copy of the receipt.\nCould you tell me whether I can have my money back or get a new pair? I would prefer a new pair, but I will accept a refund, too. I would be grateful if you could answer as soon as possible, because I need the headphones for school.\nYours faithfully,\nXYZ","modelNotes":{"summary":["Reklamacja zawiera wszystkie podpunkty: co i kiedy kupiono, na czym polega usterka, prośba o zwrot lub wymianę oraz o szybką odpowiedź.","Struktura jest logiczna: cel maila, zamówienie, opis problemu, żądanie i uprzejme zakończenie.","Ton jest formalny (Dear Sir or Madam, Yours faithfully, would be grateful), z konkretnymi szczegółami: data, załączniki.","Najsłabszym punktem jest skrót w pierwszym zdaniu – w formalnym mailu lepiej unikać skrótów."],"annotations":[{"anchor":"I'm writing to complain about a product","type":"uwaga","criterion":"zakres","note":"Do poprawy: w formalnym mailu lepiej I am writing (bez skrótu). Pozostałe zdania mają pełne formy, więc ten skrót wyróżnia się na minus."},{"anchor":"On 3 October I ordered a pair of wireless headphones","type":"punkty","criterion":"tresc","element":1,"note":"Podpunkt 1: co i kiedy kupiono – data i przedmiot w jednym zdaniu."},{"anchor":"Unfortunately, the left headphone does not work at all","type":"struktura","criterion":"spojnosc","note":"Zdanie otwierające akapit o usterce: od razu widać, że zaczyna się opis problemu."},{"anchor":"and the sound in the right one is very quiet","type":"punkty","criterion":"tresc","element":2,"note":"Podpunkt 2: druga część usterki – obie wady są nazwane konkretnie."},{"anchor":"I have charged them several times, but nothing has changed","type":"lacznik","criterion":"spojnosc","note":"But wprowadza kontrast między próbą naprawy a brakiem efektu. Present Perfect pasuje do skutków do dziś."},{"anchor":"I have attached a photo of the product and a copy of the receipt","type":"zakres","criterion":"zakres","note":"Typowe słownictwo reklamacji (attach, receipt) i Present Perfect – podnosi zakres i wiarygodność."},{"anchor":"whether I can have my money back or get a new pair","type":"punkty","criterion":"tresc","element":3,"note":"Podpunkt 3: zwrot pieniędzy lub nowy produkt – obie opcje podane w jednym pytaniu pośrednim."},{"anchor":"I would be grateful if you could answer as soon as possible","type":"rejestr","criterion":"zakres","element":4,"note":"Podpunkt 4 (szybka odpowiedź) w formalnej formule would be grateful if you could – grzeczne, ale stanowcze."}]}},{"id":"blog-hobby","genre":"blog","part":1,"title":"Wpis na blogu – hobby","opening":"Hi, readers!","prompt":"Prowadzisz bloga o czasie wolnym. Napisz o swoim hobby.\n\nW tekście:\n• napisz, czym się interesujesz\n• wyjaśnij, od kiedy to robisz\n• opowiedz o swoim największym sukcesie\n• poradź, jak zacząć","bullets":["napisz, czym się interesujesz","wyjaśnij, od kiedy to robisz","opowiedz o swoim największym sukcesie","poradź, jak zacząć"],"points":12,"genreChecklist":["Czy odniosłem/am się do wszystkich 4 punktów?","Czy mam 100–150 wyrazów?","Czy mam wstęp i zakończenie?"],"model":"Hi, readers!\nToday I want to write about my hobby, which is photography. I take pictures of nature, mostly in the forest near my house. I started three years ago when my dad gave me his old camera.\nMy biggest success was last spring, when my photo of a fox won a school competition. I was very surprised, because I didn't think it was good enough. The prize was a small tripod, which I use every day now.\nIf you would like to start, you don't need an expensive camera. Your phone is enough. Go for a walk, look around and take pictures of things that you like. After some time you will notice small details that you have never seen before. Good luck!\nXYZ","modelNotes":{"summary":["Wpis realizuje wszystkie cztery podpunkty: hobby, początek, największy sukces i rada, jak zacząć.","Narracja jest chronologiczna (three years ago, last spring), a rada na końcu daje czytelnikowi coś praktycznego.","Zdania względne (which I use every day now) i uzasadnienia (because) pokazują zróżnicowanie struktur.","Początek mógłby szybciej przejść do rzeczy – pierwsze zdanie zapowiada temat zamiast od razu go rozwijać."],"annotations":[{"anchor":"Today I want to write about","type":"uwaga","criterion":"zakres","note":"Do poprawy: zapowiedź tematu zajmuje słowa limitu. Wystarczyłoby od razu napisać, że hobby to fotografia."},{"anchor":"my hobby, which is photography","type":"punkty","criterion":"tresc","element":1,"note":"Podpunkt 1: czym się interesuję – zdanie względne zamiast samego rzeczownika."},{"anchor":"I started three years ago when my dad gave me his old camera","type":"punkty","criterion":"tresc","element":2,"note":"Podpunkt 2: od kiedy – okres (three years ago) i okoliczność, czyli prezent od taty."},{"anchor":"when my photo of a fox won a school competition","type":"punkty","criterion":"tresc","element":3,"note":"Podpunkt 3: największy sukces – konkretna historia (lis, szkolny konkurs)."},{"anchor":"I was very surprised, because I didn't think it was good enough","type":"lacznik","criterion":"spojnosc","note":"Because wyjaśnia emocję. Good enough pokazuje frazę, która wykracza poza prosty przymiotnik."},{"anchor":"which I use every day now","type":"zakres","criterion":"zakres","note":"Zdanie względne dodaje informację o nagrodzie bez osobnego zdania – płynne, choć nie wykracza poza standard."},{"anchor":"If you would like to start","type":"struktura","criterion":"spojnosc","note":"Rada otwarta zdaniem z If: od razu widać, że akapit dotyczy podpunktu 4."},{"anchor":"you don't need an expensive camera","type":"rejestr","criterion":"zakres","note":"Rozmowna, krótka rada z don't – ton bloga skierowanego do rówieśników."},{"anchor":"Go for a walk, look around and take pictures of things that you like","type":"punkty","criterion":"tresc","element":4,"note":"Podpunkt 4: jak zacząć – trzy proste polecenia, które czytelnik może wykonać od razu."}]}},{"id":"email-invite","genre":"email","part":1,"title":"E-mail – zaproszenie","opening":"Hi Anna,","prompt":"Organizujesz wspólne wyjście do kina dla klasy. Napisz e-mail do koleżanki.\n\nW tekście:\n• napisz, na jaki film chcesz iść i kiedy\n• wyjaśnij, dlaczego wybrałeś/aś ten film\n• zapytaj, czy ma jakieś preferencje co do miejsca\n• poproś o odpowiedź do piątku","bullets":["napisz, na jaki film chcesz iść i kiedy","wyjaśnij, dlaczego wybrałeś/aś ten film","zapytaj, czy ma jakieś preferencje co do miejsca","poproś o odpowiedź do piątku"],"points":12,"genreChecklist":["Czy odniosłem/am się do wszystkich 4 punktów?","Czy mam 100–150 wyrazów?","Czy mam wstęp i zakończenie?"],"model":"Hi Anna,\nI hope you are well. I'm writing because our class is going to the cinema next Saturday at 6 p.m., and I'd love you to come with us. We want to see the new science fiction film, which has great reviews.\nI chose this film because many people in our class like this genre and the story is supposed to be exciting. I've also heard that the special effects are amazing.\nWould you prefer to sit in the front or at the back? And do you want to meet in front of the cinema or go there together from school? Please let me know by Friday so that I can book the tickets.\nSee you soon,\nXYZ","modelNotes":{"summary":["Zaproszenie na film realizuje wszystkie cztery podpunkty, ale pierwszy tylko częściowo – brakuje tytułu filmu.","Tekst ma logiczną kolejność: zaproszenie, uzasadnienie, pytania o miejsce i prośba o odpowiedź.","Struktury (is supposed to be, I've also heard that) i dobre pytania o preferencje pokazują wyraźny zakres językowy.","Ton jest uprzejmy, nieformalny i bez błędów, więc o ocenie decyduje głównie pełność treści."],"annotations":[{"anchor":"I hope you are well","type":"rejestr","criterion":"zakres","note":"Uprzejmy, nieformalny początek – ton odpowiedni dla koleżanki z klasy."},{"anchor":"our class is going to the cinema next Saturday at 6 p.m.","type":"punkty","criterion":"tresc","element":1,"note":"Podpunkt 1: kiedy – dzień i godzina podane dokładnie."},{"anchor":"and I'd love you to come with us","type":"struktura","criterion":"spojnosc","note":"Zaproszenie wprost po informacji o terminie – tekst ma jasny cel."},{"anchor":"We want to see the new science fiction film","type":"uwaga","criterion":"tresc","element":1,"note":"Do poprawy: podpunkt 1 pyta o film, a tekst podaje tylko gatunek. Tytuł byłby pełniejszą odpowiedzią."},{"anchor":"I chose this film because many people in our class like this genre","type":"punkty","criterion":"tresc","element":2,"note":"Podpunkt 2: dlaczego ten film – powód nawiązuje do gustu klasy."},{"anchor":"the story is supposed to be exciting","type":"zakres","criterion":"zakres","note":"Be supposed to wyraża powszechną opinię, a nie własną – ciekawsze niż sam przymiotnik exciting."},{"anchor":"I've also heard that the special effects are amazing","type":"lacznik","criterion":"spojnosc","note":"Also dodaje kolejny argument. I've heard that to informacja z drugiej ręki – brzmi wiarygodnie i naturalnie."},{"anchor":"Would you prefer to sit in the front or at the back?","type":"punkty","criterion":"tresc","element":3,"note":"Podpunkt 3: pytanie o preferencje co do miejsca – grzeczne Would you prefer."},{"anchor":"Please let me know by Friday so that I can book the tickets","type":"punkty","criterion":"tresc","element":4,"note":"Podpunkt 4: prośba o odpowiedź do piątku z uzasadnieniem (so that)."}]}}]},"trening-mowienie":{"id":"trening-mowienie","version":1,"format":"matura","note":"Czasy orientacyjne. Aktualny przebieg i punktację sprawdź w informatorze CKE.","criteria":[{"id":"komunikacja","label":"Realizacja zadania","hint":"Odnoszę się do wszystkich elementów i rozwijam odpowiedzi."},{"id":"zakres","label":"Zakres środków językowych","hint":"Różne struktury i słownictwo, nie tylko podstawowe."},{"id":"poprawnosc","label":"Poprawność","hint":"Mało błędów, które przeszkadzają w zrozumieniu."},{"id":"wymowa","label":"Wymowa i płynność","hint":"Mówię wyraźnie, bez długich przerw."}],"intro":{"title":"Rozmowa wstępna","seconds":120,"groups":[{"id":"intro-czas-wolny","topic":"Życie prywatne","questions":["What do you usually do after school?","Tell me about something interesting you did last weekend.","Would you rather spend a free day at home or outdoors? Why?"]},{"id":"intro-rodzina-przyjaciele","topic":"Człowiek","questions":["Can you tell me a little about your best friend?","What do you and your family like doing together?","Who is the person you admire most? Why?","How would your friends describe you?"]},{"id":"intro-miasto","topic":"Miejsce zamieszkania","questions":["Where do you live? Tell me about your town or village.","What do you like most about your neighbourhood?","Would you like to live in the same place in the future? Why or why not?"]},{"id":"intro-szkola","topic":"Edukacja","questions":["What is your favourite school subject and why?","Tell me about a teacher who has helped you a lot.","What would you change about your school if you could?","How do you usually prepare for tests?"]},{"id":"intro-praca","topic":"Praca","questions":["Do you have a part-time job, or would you like to have one?","What job would you like to do in the future?","Do you think it is a good idea for teenagers to work during the school year?"]},{"id":"intro-jedzenie","topic":"Żywienie","questions":["What did you have for breakfast today?","Do you ever cook at home? Tell me about it.","What is a traditional Polish dish you would recommend to a visitor?","Do you think you eat healthily? Why?"]},{"id":"intro-zakupy","topic":"Zakupy i usługi","questions":["Do you prefer shopping in shops or online? Why?","Tell me about the last thing you bought for yourself.","How often do you go to the shopping centre in your town?"]},{"id":"intro-wakacje","topic":"Podróżowanie i turystyka","questions":["Where did you spend your last holiday?","Do you prefer holidays by the sea or in the mountains? Why?","Which country would you most like to visit and why?","Tell me about a trip you will never forget."]},{"id":"intro-zdrowie","topic":"Zdrowie","questions":["What do you do to stay healthy?","How much sleep do you usually get on a school night?","What do you do when you feel stressed before an exam?"]},{"id":"intro-sport","topic":"Sport","questions":["Do you do any sport regularly? Tell me about it.","Do you like watching sport on TV or going to matches?","Which sport would you like to try one day, and why?","Is sport an important subject at your school?"]}]},"roleplay":{"title":"Zadanie 1 – rozmowa z odgrywaniem roli","prepSeconds":30,"seconds":240,"cards":[{"id":"rp-koncert","topic":"Kultura","situation":"Jesteś w Londynie na wymianie. Chcesz pójść ze znajomym z Anglii (egzaminator) na koncert. Rozmawiacie o planie.","elements":["rodzaj muzyki","cena biletów","dojazd na koncert","co zrobicie po koncercie"],"examinerLines":["Hi! So, you said you wanted to go to a concert this weekend?","Hmm, I'm not a big fan of that kind of music. What else could we see?","Tickets in London can be really expensive. How much do you want to spend?","How are we going to get there? It finishes quite late.","And what about afterwards? Any ideas?"],"usefulPhrases":["How about going to …?","I'd rather … than …","That sounds good, but …","We could always …"]},{"id":"rp-egzamin-nauka","topic":"Edukacja","situation":"Za dwa tygodnie masz ważny egzamin. Rozmawiasz z koleżanką z klasy (egzaminator) o wspólnej nauce.","elements":["miejsce nauki","godziny spotkań","materiały do nauki","przerwy i nagrody po nauce"],"examinerLines":["Hi! I heard you're also nervous about the exam. Shall we study together?","Well, my house is a bit noisy at the moment. Where else could we go?","I have football training on Tuesdays and Thursdays, so I'm not free then. When suits you?","I don't have many notes, to be honest. What could we use?","Don't you think we'll get bored? What shall we do to make it more fun?"],"usefulPhrases":["Why don't we …?","It would be better if …","I'm free on …","That's a good point, but …"]},{"id":"rp-praca-wakacyjna","topic":"Praca","situation":"Szukasz pracy wakacyjnej. Rozmawiasz z właścicielem małej kawiarni (egzaminator), który szuka pracownika na lato.","elements":["twoje doświadczenie","dni i godziny, w których możesz pracować","zakres obowiązków","wynagrodzenie"],"examinerLines":["Good morning! Thanks for coming. Have you worked in a café before?","I see. And when would you be able to start?","We're very busy at weekends. Could you work on Saturdays and Sundays?","We need help both behind the counter and in the kitchen. What would you prefer to do?","I can only offer a fairly low hourly rate at the beginning. Is that all right?"],"usefulPhrases":["I'd be happy to …","I have some experience of …","I'm available from … to …","Could you tell me more about …?"]},{"id":"rp-urodziny","topic":"Życie prywatne","situation":"Twój najlepszy przyjaciel Tom ma niedługo urodziny. Razem z jego siostrą (egzaminator) organizujecie dla niego przyjęcie-niespodziankę.","elements":["miejsce przyjęcia","lista gości","prezent","sposób zachowania tajemnicy"],"examinerLines":["Hi! Have you got a minute? I'd love to plan something special for Tom's birthday.","We can't have it at his house, of course. Where could we hold it?","I'm not sure we should invite too many people. What do you think?","A gift is a problem. He's got almost everything. Any ideas?","He's very curious and always asks questions. How can we keep it a secret?"],"usefulPhrases":["What about …?","I suggest that we …","I'm not sure that's a good idea because …","Let's make sure that …"]},{"id":"rp-restauracja","topic":"Żywienie","situation":"Jesteś w restauracji w Brighton z rodziną znajomego. Rozmawiasz z kelnerem (egzaminator) o zamówieniu.","elements":["danie główne","dieta lub alergia","napoje","deser i rachunek"],"examinerLines":["Good evening! Are you ready to order?","I'm sorry, that dish isn't available today. Would you like something else?","Do you have any food allergies I should know about?","Would you like anything to drink with your meal?","Shall I bring you the dessert menu, or would you like the bill?"],"usefulPhrases":["I'd like to have …","Could I have … instead?","I'm allergic to …","Could we have the bill, please?"]},{"id":"rp-reklamacja","topic":"Zakupy i usługi","situation":"Kupiłeś/-aś w sklepie internetowym słuchawki, które nie działają. Dzwonisz do obsługi klienta, rozmawia z Tobą konsultant (egzaminator).","elements":["opis problemu","kiedy kupiłeś/-aś produkt i jak za niego zapłaciłeś/-aś","czego oczekujesz (zwrot pieniędzy lub wymiana)","sposób odesłania towaru"],"examinerLines":["Hello, customer service. How can I help you?","I'm sorry to hear that. When did you buy them?","Have you got your order number?","Would you prefer a refund or a replacement?","You'll have to pay for the postage yourself, I'm afraid. Is that OK?"],"usefulPhrases":["I'm calling because …","It stopped working after …","I'd like a refund, please.","I'm afraid that's not fair because …"]},{"id":"rp-weekend-krakow","topic":"Podróżowanie i turystyka","situation":"Planujesz z kolegą z Irlandii (egzaminator), który odwiedza Polskę, weekendową wycieczkę po kraju. Ustalacie szczegóły.","elements":["dokąd pojedziecie","środek transportu","nocleg","atrakcje na miejscu"],"examinerLines":["Hi! I've got two free days. Where would you like to take me?","I'm not keen on long journeys. How should we travel?","Hotels can be quite pricey. Where could we stay?","Is there anything interesting to do there, apart from sightseeing?","It might rain all weekend, you know. Do we have a plan B?"],"usefulPhrases":["I'd recommend …","It takes about … hours by …","If the weather is bad, we could …","You really should try …"]},{"id":"rp-klub-sportowy","topic":"Sport","situation":"Chcesz zapisać się do klubu sportowego w swoim mieście. Rozmawiasz z trenerem (egzaminator), który odpowiada za nowych członków.","elements":["dyscyplina, którą chcesz trenować","twoje dotychczasowe doświadczenie","dni treningowe","koszt członkostwa"],"examinerLines":["Hello! Welcome to our club. What kind of sport are you interested in?","Have you done this sport before, or are you a complete beginner?","Our groups train three times a week. Is that too much for you?","You'd need your own equipment, which isn't cheap. Is that a problem?","The monthly fee is quite high. Would you like to try a free lesson first?"],"usefulPhrases":["I've been playing … for …","I'm quite keen on …","I'm afraid I can't … because …","Could I try it first?"]},{"id":"rp-wizyta-lekarz","topic":"Zdrowie","situation":"Źle się czujesz i jesteś na wizycie u lekarza w Londynie. Rozmawiasz z lekarzem (egzaminator).","elements":["objawy","od kiedy się źle czujesz","leki, które już brałeś/-aś","czy możesz iść jutro do szkoły"],"examinerLines":["Good morning. What seems to be the problem?","How long have you been feeling like this?","Have you taken anything for it?","I think you should stay at home for a few days. How do you feel about that?","You'll need some rest. Is there anything you'd like to ask me?"],"usefulPhrases":["I've got a sore throat.","It started on …","I took some … but it didn't help.","Do I have to …?"]},{"id":"rp-telefon","topic":"Nauka i technika","situation":"Chcesz kupić nowy telefon. Prosisz o radę starszego brata, który zna się na technice (egzaminator).","elements":["do czego będziesz używać telefonu","budżet","marka i funkcje","gdzie kupić telefon"],"examinerLines":["So, you're thinking of getting a new phone? What do you need it for?","Phones can cost a fortune these days. How much can you spend?","Honestly, I don't think the brand matters. Which features are the most important to you?","Should we buy it online or go to a shop? I'm not sure which is better.","Why not just keep your old one for another year?"],"usefulPhrases":["I mainly use it for …","I can't spend more than …","It's essential that it has …","On the other hand, …"]},{"id":"rp-wymiana-mieszkanie","topic":"Miejsce zamieszkania","situation":"Właśnie przyjechałeś/-aś na wymianę do Manchesteru. Rozmawiasz z panią domu w rodzinie goszczącej (egzaminator) o zasadach.","elements":["pokój i jego wyposażenie","godziny posiłków","obowiązki domowe","wracanie wieczorem do domu"],"examinerLines":["Welcome to our home! Let me show you your room. Is there anything you need?","We usually have dinner at six. Is that all right for you?","Everyone here helps with the housework. Would you mind doing the washing-up?","We'd like you to be home by ten o'clock. Does that seem too early?","Is there anything else you'd like to ask about living here?"],"usefulPhrases":["Would it be possible to …?","I don't mind …","That's fine with me.","I'd prefer to … if that's OK."]},{"id":"rp-wolontariat","topic":"Życie społeczne","situation":"Chcesz zostać wolontariuszem w schronisku dla zwierząt. Rozmawiasz z koordynatorką wolontariuszy (egzaminator).","elements":["dlaczego chcesz pomagać","dni, w które możesz przychodzić","rodzaj pracy, który wolisz","co chcesz zyskać z tego doświadczenia"],"examinerLines":["Hello! Thanks for your interest in volunteering with us. Why do you want to help?","We need people most on weekday afternoons. Is that possible for you?","The work isn't always pleasant. Some jobs involve cleaning cages. Does that bother you?","Lots of young people give up after a month. How can you convince me you'll stay?","What would you like to learn from this experience?"],"usefulPhrases":["I'd really like to help because …","I'm happy to do any kind of work.","I can promise that …","It would be a great chance to …"]}]},"picture":{"title":"Zadanie 2 – opis ilustracji i pytania","seconds":180,"cards":[{"id":"pic-kuchnia","topic":"Żywienie","description":"A family of four is cooking together in a small, bright kitchen. The father is cutting vegetables, the mother is reading a recipe on a tablet, and two teenagers are setting the table and laughing. There is a large pot on the cooker and a bowl of salad on the counter. Through the window you can see that it is raining.","questions":["Why do you think the family decided to cook together?","Tell me about a time when you cooked something for other people.","Do you think young people today know how to cook? Why?"],"usefulPhrases":["In the picture I can see …","In the foreground / background …","It looks like …","I think they're feeling …"]},{"id":"pic-przyjaciele-park","topic":"Człowiek","description":"Three friends are sitting on a bench in a park on a sunny afternoon. One girl is showing something funny on her phone, and the other two are laughing. One of the boys, who has a backpack, is eating an ice cream. Behind them there are tall trees, and a man is walking a small brown dog along the path. In the distance you can see a playground.","questions":["What do you think the friends are talking about?","Tell me about your closest friends and how you spend time together.","Is it better to have a few close friends or lots of friends? Why?"],"usefulPhrases":["They seem to be …","In the background there is …","What I like about my friends is …","In my opinion, …"]},{"id":"pic-nowy-blok","topic":"Miejsce zamieszkania","description":"A young couple is carrying cardboard boxes into a block of flats. A removal van is parked in front of the building, and a man in a blue uniform is lifting a sofa. An elderly woman is looking out of a window on the second floor and smiling. There is a small playground and a few bicycles next to the entrance. The sky is grey, but nobody seems to mind.","questions":["Why do you think the couple are moving to this flat?","Tell me about the place where you live. What do you like and dislike about it?","Would you prefer to live in a flat or in a house? Why?"],"usefulPhrases":["The picture shows …","On the left / on the right …","They're probably moving because …","I'd rather live in … because …"]},{"id":"pic-lekcja-chemii","topic":"Edukacja","description":"A group of teenagers in white lab coats are doing an experiment in a school laboratory. A girl is carefully pouring a blue liquid into a test tube, while a boy next to her is writing notes. The teacher, a tall woman with glasses, is standing behind them and watching. On the wall there is a big poster of the periodic table, and some students at the back look a bit bored.","questions":["How do you think the students feel during this lesson?","Tell me about a lesson at school that you really enjoyed.","Do you think practical lessons are better than lessons with only a textbook? Why?"],"usefulPhrases":["In the middle of the picture …","The students are wearing …","I remember a lesson when …","It's more interesting to … than to …"]},{"id":"pic-biuro","topic":"Praca","description":"Four people are having a meeting in a modern office. A woman in a grey suit is standing next to a screen and pointing at a graph. Two men are sitting at a long table with laptops and coffee cups, and one of them is yawning. A young woman is taking notes. Behind them there are large windows and you can see tall buildings outside.","questions":["What do you think the meeting is about?","Would you like to work in an office in the future? Why or why not?","What is more important in a job: a high salary or a pleasant atmosphere?"],"usefulPhrases":["I can see …","She looks quite …","It must be … to work in …","For me, the most important thing is …"]},{"id":"pic-targ","topic":"Zakupy i usługi","description":"A busy outdoor market on a sunny morning. A man behind a stall is weighing tomatoes for an elderly customer. Other stalls sell fruit, flowers and cheese. A mother with two children is carrying a big paper bag, and a girl is trying a piece of apple. There are colourful umbrellas above the stalls, and in the background you can see a church.","questions":["Why do you think so many people are shopping at the market?","Tell me about the last time you went shopping with your family or friends.","Do you prefer buying food at a market or in a supermarket? Why?"],"usefulPhrases":["The scene takes place …","There are lots of people …","One advantage of … is that …","I usually go shopping …"]},{"id":"pic-dworzec","topic":"Podróżowanie i turystyka","description":"A crowded railway station in summer. A couple with large suitcases is looking at a departure board and seems a little worried. A young man with a guitar on his back is sitting on the floor and drinking water. Next to him a girl is reading a map. Some tourists are taking photos of a big clock. Behind them a train is arriving at the platform.","questions":["Why do you think the couple look worried?","Tell me about a journey by train or bus that you remember well.","Do you prefer travelling by train, by car or by plane? Why?"],"usefulPhrases":["At the front of the picture …","They might be waiting for …","Once I travelled to …","What I like most about travelling by … is …"]},{"id":"pic-uliczni-muzycy","topic":"Kultura","description":"Two street musicians are playing in a busy square in the evening. One of them plays the violin, and the other is singing and holding a hat for money. A small crowd has stopped to listen, and some people are filming them with their phones. A little boy is dancing in front of the musicians, while his father is smiling. The lights are on in the cafés behind them.","questions":["How do you think the people in the audience feel?","Tell me about a concert or another cultural event you have been to.","Do you like it when musicians play in the street? Why?"],"usefulPhrases":["The atmosphere seems …","It looks as if …","I once went to …","I'm in favour of / against …"]},{"id":"pic-mecz-szkolny","topic":"Sport","description":"A school volleyball match is taking place in a sports hall. A girl in a red shirt is jumping up to hit the ball over the net, and her team-mates are watching with excitement. On one side, a group of students are cheering and holding a banner. The teacher is standing near the net with a whistle. The scoreboard shows that the match is very close.","questions":["Why do you think the match is so exciting for the students?","Tell me about a sport event you took part in or watched.","Do you think competition at school is a good thing? Why or why not?"],"usefulPhrases":["In the foreground …","The players seem to be …","I took part in …","On the one hand …, on the other hand …"]},{"id":"pic-przychodnia","topic":"Zdrowie","description":"A small waiting room in a doctor's surgery. A mother is holding a little girl who has a red nose and is sneezing. An old man next to them is reading a newspaper, and a teenage boy is holding his arm and looking tired. A nurse is talking to the receptionist behind a desk. On the wall there is a poster about washing hands, and a plant stands in the corner.","questions":["Why do you think these people are in the surgery?","Tell me about the last time you were ill. What did you do?","What can people do to avoid getting ill in autumn and winter?"],"usefulPhrases":["It seems that …","They are probably …","When I was ill, I …","It's a good idea to …"]},{"id":"pic-robot-szkola","topic":"Nauka i technika","description":"In a school classroom, a group of students are building a small robot. A boy is connecting wires, and a girl is typing something into a laptop. Another student is holding a screwdriver and looking at the instructions. On the table there are tools, a few small motors and a cup of tea. The teacher is smiling and taking a photo of the project.","questions":["What do you think the students are learning from this project?","Tell me about a gadget or an app that you use every day.","Do you think technology makes our lives easier or more complicated? Why?"],"usefulPhrases":["The students appear to be …","I can't live without …","It saves a lot of time because …","The main disadvantage is that …"]},{"id":"pic-las","topic":"Świat przyrody","description":"A group of children and two adults are walking through a forest in autumn. The ground is covered with orange and yellow leaves. One boy is picking up a mushroom, but a woman is pointing at it and shaking her head. A girl is taking a photo of a squirrel on a tree. Another child is carrying a big rubbish bag. The light between the trees is soft and golden.","questions":["Why do you think the group have come to the forest?","Tell me about a day you spent outdoors in nature.","What can young people do to protect the environment?"],"usefulPhrases":["The picture was taken in …","The weather seems to be …","I really enjoy being …","We should all try to …"]}]},"choice":{"title":"Zadanie 3 – wybór i uzasadnienie","prepSeconds":60,"seconds":240,"cards":[{"id":"ch-wycieczka-klasowa","topic":"Podróżowanie i turystyka","situation":"Twoja klasa wybiera miejsce jednodniowej wycieczki na koniec roku szkolnego.","options":["A group of students hiking on a mountain trail with a guide.","Students in a science centre trying interactive experiments.","Teenagers kayaking on a quiet river on a sunny day."],"criteria":["Wybierz miejsce, które będzie najlepsze dla całej klasy, i uzasadnij swój wybór.","Wyjaśnij, dlaczego odrzucasz pozostałe propozycje."],"questions":["Why is it important for classmates to spend time together outside school?","Tell me about the most memorable school trip you have been on."]},{"id":"ch-nowe-mieszkanie","topic":"Miejsce zamieszkania","situation":"Twoja rodzina przeprowadza się i wybiera nowe miejsce zamieszkania. Chcesz doradzić rodzicom, które będzie najlepsze.","options":["A flat in the centre of a big city, close to shops and cinemas.","A detached house with a garden in a quiet village.","A small house in a suburb, near a school and a park."],"criteria":["Wybierz miejsce, które będzie najlepsze dla całej rodziny, i uzasadnij wybór.","Wyjaśnij, dlaczego pozostałe opcje są mniej wygodne."],"questions":["What are the advantages and disadvantages of living in a big city?","Would you like to live abroad one day? Why or why not?"]},{"id":"ch-kolo-zainteresowan","topic":"Edukacja","situation":"W Twojej szkole ruszają nowe zajęcia dodatkowe. Możesz wybrać tylko jedne i musisz uzasadnić wybór.","options":["Students rehearsing a play in a drama club on a small stage.","Teenagers practising coding together in a bright school computer room.","A group of students learning to paint in an art studio."],"criteria":["Wybierz zajęcia, które będą najbardziej przydatne dla Ciebie, i uzasadnij wybór.","Wyjaśnij, dlaczego nie wybierasz pozostałych zajęć."],"questions":["Why is it good for students to have after-school activities?","Which skills do you think are the most useful for finding a job?"]},{"id":"ch-praca-wakacje","topic":"Praca","situation":"Chcesz dorobić podczas wakacji. Masz trzy oferty pracy i musisz zdecydować, którą przyjąć.","options":["A young person working as a lifeguard at a swimming pool.","A teenager delivering pizzas on a scooter in the evening.","A student helping children at a summer camp."],"criteria":["Wybierz ofertę, która najbardziej Ci odpowiada, i uzasadnij wybór.","Wyjaśnij, dlaczego rezygnujesz z pozostałych ofert."],"questions":["Do you think teenagers should earn their own money? Why?","Tell me about a job you would never want to do."]},{"id":"ch-prezent-babcia","topic":"Życie prywatne","situation":"Twoja babcia ma 70. urodziny. Razem z rodzeństwem wybieracie dla niej prezent.","options":["A framed photograph of the whole family sitting together.","A voucher for a weekend for two at a spa hotel.","An older woman video-calling her family on a new tablet."],"criteria":["Wybierz prezent, który najbardziej ucieszy babcię, i uzasadnij wybór.","Wyjaśnij, dlaczego odrzucasz pozostałe pomysły."],"questions":["Why is it important to spend time with older members of the family?","Tell me about the best present you have ever received."]},{"id":"ch-kolacja","topic":"Żywienie","situation":"Organizujesz kolację dla klasy po zakończeniu roku szkolnego. Musisz wybrać rodzaj posiłku.","options":["Students eating pizza together in a noisy, crowded restaurant.","A barbecue in a sunny garden with sausages, salads and cold drinks.","Classmates cooking pasta together in the kitchen at someone's house."],"criteria":["Wybierz opcję, która będzie najlepsza dla całej klasy, i uzasadnij wybór.","Wyjaśnij, dlaczego pozostałe opcje są gorsze."],"questions":["Do you think fast food is a problem for young people? Why?","Tell me about a meal you remember very well."]},{"id":"ch-sklep-ubrania","topic":"Zakupy i usługi","situation":"Potrzebujesz nowej kurtki na zimę i zastanawiasz się, gdzie ją kupić.","options":["A girl trying on jackets in a large shopping centre.","A boy choosing a second-hand jacket in a charity shop.","A teenager ordering a jacket on a website at home."],"criteria":["Wybierz sposób zakupu, który najbardziej Ci pasuje, i uzasadnij wybór.","Wyjaśnij, co przemawia przeciwko pozostałym możliwościom."],"questions":["Is it important for young people to follow fashion? Why or why not?","Tell me about something you bought that turned out to be a mistake."]},{"id":"ch-wieczor-kultura","topic":"Kultura","situation":"Wybierasz z przyjaciółmi, jak spędzić piątkowy wieczór w mieście.","options":["Friends watching a new film in a cinema with popcorn.","People looking at paintings in a modern art gallery.","A group of teenagers listening to a band in a small club."],"criteria":["Wybierz propozycję, która spodoba się całej grupie, i uzasadnij wybór.","Wyjaśnij, dlaczego odrzucasz pozostałe pomysły."],"questions":["Why is culture important in our lives?","Tell me about the last film or book you really liked."]},{"id":"ch-aktywnosc-sport","topic":"Sport","situation":"Chcesz zacząć regularnie ćwiczyć. Zastanawiasz się, jaka forma aktywności będzie dla Ciebie najlepsza.","options":["A teenager running in a park early in the morning.","Friends playing basketball together on an outdoor court after school.","A young person swimming lengths alone in a quiet indoor pool."],"criteria":["Wybierz aktywność, która najbardziej Ci odpowiada, i uzasadnij wybór.","Wyjaśnij, dlaczego nie wybierasz pozostałych."],"questions":["Why do some young people not do any sport?","Tell me about a time when you tried a new sport or activity."]},{"id":"ch-odpoczynek-zdrowie","topic":"Zdrowie","situation":"Po ciężkim tygodniu egzaminów chcesz dobrze odpocząć. Wybierasz sposób relaksu na weekend.","options":["A girl sleeping late and reading a book in bed.","A boy doing yoga on a mat in a quiet room with soft music.","Friends having a picnic on the grass by a calm lake."],"criteria":["Wybierz sposób odpoczynku, który najlepiej wpłynie na Twoje zdrowie, i uzasadnij wybór.","Wyjaśnij, dlaczego odrzucasz pozostałe sposoby."],"questions":["Why is it important to take breaks from studying?","Do you think teenagers today have too much homework? Why?"]},{"id":"ch-zwierze-dom","topic":"Świat przyrody","situation":"Twoja rodzina chce wziąć zwierzę do domu. Musicie zdecydować, jakie będzie najlepsze.","options":["A friendly dog that needs a long walk every day.","A cat sleeping on a sofa and playing with a toy.","A small tank with colourful fish on a shelf."],"criteria":["Wybierz zwierzę, które najlepiej pasuje do Waszej rodziny, i uzasadnij wybór.","Wyjaśnij, dlaczego pozostałe zwierzęta są mniej odpowiednie."],"questions":["Why do many people like having pets?","What can ordinary people do to protect wild animals?"]},{"id":"ch-akcja-spoleczna","topic":"Życie społeczne","situation":"Twoja szkoła organizuje akcję charytatywną. Uczniowie głosują, w jaki sposób pomóc potrzebującym.","options":["Students collecting warm clothes and toys in big boxes.","A school concert where tickets are sold for charity.","Teenagers visiting elderly people in a care home."],"criteria":["Wybierz akcję, która przyniesie największą korzyść, i uzasadnij wybór.","Wyjaśnij, dlaczego pozostałe pomysły są mniej skuteczne."],"questions":["Why is it important for young people to help others?","Tell me about a time when you helped someone."]}]}}},"exercises":{"mp-srodki-cloze-1":{"id":"mp-srodki-cloze-1","part":1,"type":"multiple-choice-cloze","title":"A day at the beach","instructions":"Wybierz słowo (A, B, C lub D), które najlepiej pasuje do luki. Każda luka to 1 punkt.","maxScore":8,"text":"Last summer we {{1}} a trip to the seaside. We got up early because the train {{2}} at six. When we arrived, the weather was lovely, so we {{3}} a swim at once. After lunch my brother {{4}} a sandcastle while I was reading. {{5}} the afternoon it started to rain, and we had to look for shelter. We spent two hours in a small café {{6}} hot chocolate. It was not the day we had planned, but we {{7}} a great time. I hope we can {{8}} there again next year.","gaps":[{"n":1,"options":{"A":"did","B":"took","C":"went","D":"made"},"answer":"B","explanation":"take a trip = wybrać się na wycieczkę."},{"n":2,"options":{"A":"left","B":"was leaving","C":"leaves","D":"has left"},"answer":"A","explanation":"Past Simple: pociąg odjeżdżał o szóstej (left)."},{"n":3,"options":{"A":"had","B":"made","C":"did","D":"got"},"answer":"A","explanation":"have a swim = popływać."},{"n":4,"options":{"A":"built","B":"builded","C":"was built","D":"has built"},"answer":"A","explanation":"Past Simple, nieregularny: build, built."},{"n":5,"options":{"A":"At","B":"In","C":"On","D":"By"},"answer":"B","explanation":"in the afternoon."},{"n":6,"options":{"A":"drink","B":"drinking","C":"drunk","D":"to drink"},"answer":"B","explanation":"Zwrot z -ing opisujący czynność: drinking hot chocolate."},{"n":7,"options":{"A":"had","B":"made","C":"took","D":"gave"},"answer":"A","explanation":"have a great time = świetnie się bawić."},{"n":8,"options":{"A":"going","B":"go","C":"to go","D":"went"},"answer":"B","explanation":"Po can czasownik w formie podstawowej: can go."}]},"mp-srodki-slowotworstwo-1":{"id":"mp-srodki-slowotworstwo-1","part":3,"type":"word-formation","title":"A volunteer weekend","instructions":"Utwórz od słowa w nawiasie słowo, które pasuje do luki. Uważaj na przedrostki, liczbę mnogą i pisownię. Każda luka to 1 punkt.","maxScore":8,"text":"Last weekend I took part in a {{1}} project in our town. It was a very {{2}} experience for me. At first I felt a bit {{3}} because I didn't know anyone. However, the other volunteers were {{4}} and soon we became friends. We cleaned the river bank {{5}} and collected a lot of rubbish left by visitors. The organisers thanked us for our {{6}} and promised to send each of us a small {{7}}. I'm sure I will join them again, because I think {{8}} others is important.","gaps":[{"n":1,"stem":"VOLUNTEER","accept":["VOLUNTARY"],"explanation":"Przymiotnik: voluntary project."},{"n":2,"stem":"REWARD","accept":["REWARDING"],"explanation":"Przymiotnik: rewarding experience."},{"n":3,"stem":"COMFORT","accept":["UNCOMFORTABLE"],"explanation":"Przeczenie przymiotnika: comfort → uncomfortable."},{"n":4,"stem":"FRIEND","accept":["FRIENDLY"],"explanation":"Przymiotnik: friendly."},{"n":5,"stem":"CARE","accept":["CAREFULLY"],"explanation":"Przysłówek: carefully."},{"n":6,"stem":"CONTRIBUTE","accept":["CONTRIBUTION"],"explanation":"Rzeczownik po our: contribution."},{"n":7,"stem":"CERTIFY","accept":["CERTIFICATE"],"explanation":"Rzeczownik: a small certificate."},{"n":8,"stem":"HELP","accept":["HELPING"],"explanation":"Rzeczownik odczasownikowy jako podmiot: helping others is important."}]}}};
